      "requirement": "R5",
      "code": "import pytest

def test_r5_error_message_deterministic_order():
    from lark import Lark
    grammar = """
        start: "a" | "b" | "c"
    """
    parser = Lark(grammar, start='start')
    try:
        parser.parse("d")
    except Exception as e:
        msg = str(e)
        lines = msg.split('\n')
        expected_lines = [line for line in lines if line.startswith('\t* ')]
        expected_tokens = [line[3:] for line in expected_lines]
        assert expected_tokens == sorted(expected_tokens), "Expected tokens should be in alphabetical order"

def test_r5_error_message_identical_across_runs():
    from lark import Lark
    grammar = """
        start: "a" | "b" | "c"
    """
    parser1 = Lark(grammar, start='start')
    parser2 = Lark(grammar, start='start')
    try:
        parser1.parse("d")
    except Exception as e1:
        msg1 = str(e1)
    try:
        parser2.parse("d")
    except Exception as e2:
        msg2 = str(e2)
    assert msg1 == msg2, "Error messages should be identical across runs"
