      "code": "import pytest

def test_r6_token_repr_evaluable():
    from lark import Token
    t = Token('INT', '42', pos_in_stream=0, line=1, column=1)
    repr_str = repr(t)
    t2 = eval(repr_str, {'Token': Token})
    assert t2.type == t.type
    assert t2.value == t.value

def test_r6_tree_repr_evaluable():
    from lark import Tree, Token
    t = Tree('add', [Token('INT', '1'), Token('INT', '2')])
    repr_str = repr(t)
    t2 = eval(repr_str, {'Tree': Tree, 'Token': Token})
    assert t2.data == t.data
    assert len(t2.children) == len(t.children)
    for c1, c2 in zip(t.children, t2.children):
        if isinstance(c1, Token):
            assert c2.type == c1.type
            assert c2.value == c1.value
        else:
            assert c2 == c1

